import csv
from pathlib import Path


ROOT = Path(__file__).resolve().parent
RESULTS = ROOT / "results"


def read_rows():
    with (RESULTS / "aggregate_summary.csv").open(newline="") as f:
        return list(csv.DictReader(f))


def pct_reduction(new, old):
    old = float(old)
    if old == 0:
        return 0.0
    return 100.0 * (float(old) - float(new)) / old


def main():
    rows = read_rows()
    by_key = {(r["method"], float(r["correlation"])): r for r in rows}
    lines = [
        "# Executed prototype results",
        "",
        "These numbers are generated by the included synthetic WSN-IoT/HFL simulator.",
        "They are implementation-validation evidence, not a substitute for real hardware or ns-3 validation.",
        "",
        "| Corr. | Method | Accuracy | Macro-F1 | Effective bits | Energy (J) | Rep. JS | Relay energy max (J) |",
        "|---:|---|---:|---:|---:|---:|---:|---:|",
    ]
    for corr in sorted({float(r["correlation"]) for r in rows}):
        for method in ("random", "resource", "utility", "proposed"):
            r = by_key[(method, corr)]
            lines.append(
                f"| {corr:.2f} | {method} | {float(r['accuracy_mean']):.4f} | "
                f"{float(r['macro_f1_mean']):.4f} | {float(r['effective_bits_mean']):.0f} | "
                f"{float(r['energy_j_mean']):.3f} | {float(r['representation_js_mean']):.4f} | "
                f"{float(r['max_relay_energy_j_mean']):.4f} |"
            )
    lines.extend(["", "## Proposed vs. resource-only baseline", ""])
    for corr in sorted({float(r["correlation"]) for r in rows}):
        p = by_key[("proposed", corr)]
        b = by_key[("resource", corr)]
        lines.append(
            f"- **Correlation {corr:.2f}:** effective expected bits "
            f"{pct_reduction(p['effective_bits_mean'], b['effective_bits_mean']):.1f}% lower; "
            f"energy {pct_reduction(p['energy_j_mean'], b['energy_j_mean']):.1f}% lower; "
            f"representation JS {pct_reduction(p['representation_js_mean'], b['representation_js_mean']):.1f}% lower; "
            f"accuracy {float(p['accuracy_mean']) - float(b['accuracy_mean']):+.4f} absolute."
        )
    lines.extend([
        "",
        "The simulator intentionally models correlated statistical/system heterogeneity,",
        "multi-hop expected-transmission cost, relay-energy externality, adaptive update sparsification",
        "with error feedback, and utility-aware staleness weighting.",
        "",
    ])
    (ROOT / "RESULTS.md").write_text("\n".join(lines))
    print(ROOT / "RESULTS.md")


if __name__ == "__main__":
    main()
